import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Open Cube OS documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function n(o,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="open-cube-os-documentation" tabindex="-1">Open Cube OS documentation <a class="header-anchor" href="#open-cube-os-documentation" aria-label="Permalink to &quot;Open Cube OS documentation&quot;">​</a></h1><p>Welcome to the documentation center for Open Cube OS - the from-scratch x86_64 kernel that boots into ring 3 (L0 is a pure service kernel; the whole user world - the ush shell, the TUI desktop, the Chinese console, the 8 merged mega-apps - lives in L1 under <code>ocos/l1apps/</code>).</p><p>Everything here is written against the real tree: command counts, interface tables and line statistics are machine-generated (<code>make api-docs</code> -&gt; <code>docs/data/*.json</code>), and the manual pages cite the file that implements what they describe.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li>New to the system: <a href="./manual/getting-started.html">Getting started</a></li><li>The command surface: <a href="./manual/mega-apps.html">The 8 merged mega-apps</a></li><li>Want to build it: <a href="./dev/environment.html">Development environment</a> then <a href="./root/BUILDING.html">BUILDING.md</a></li><li>Want to extend it: <a href="./l1/overview.html">Ring-3 app development</a></li><li>Architecture questions: <a href="./root/ARCHITECTURE.html">ARCHITECTURE.md</a> then the deep dives under <a href="./arch/">arch/</a></li><li>Something broke: <a href="./troubleshooting/common-errors.html">Troubleshooting</a></li><li>Every command, including the hidden ones: <a href="./manual/function-dictionary.html">Function dictionary</a> then <a href="./manual/hidden-commands.html">Hidden commands &amp; test stubs</a></li><li>Every error the system can emit: <a href="./troubleshooting/error-codes.html">Error codes</a> then the <a href="./troubleshooting/error-catalog.html">full error catalog</a></li><li>The whole picture, hidden corners included: <a href="./arch/system-map.html">System map</a>, <a href="./arch/tree-map.html">tree map</a>, <a href="./arch/hidden-mechanisms.html">hidden mechanisms</a></li><li>Every interface: <a href="./dev/interface-dictionary.html">L1SVC dictionary (208 ops)</a>, <a href="./dev/syscall-reference.html">syscall reference (54)</a>, <a href="./dev/data-structures.html">kernel data structures</a></li><li>The merged-app story: <a href="./release/3.0.0-WP-l1apps-merge.html">3.0.0-WP-l1apps-merge</a></li></ul><h2 id="the-library" tabindex="-1">The library <a class="header-anchor" href="#the-library" aria-label="Permalink to &quot;The library&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./manual/">manual/</a></td><td>User manual: the mega-apps, boot, shell, files, network, TUI, OTA, recovery, the 296-command function dictionary, hidden commands &amp; 93 test stubs + all 292 command pages</td></tr><tr><td><a href="./dev/">dev/</a></td><td>Developer handbook: environment, build, the L1SVC interface dictionary (208 ops), syscall reference, data structures, call chains, debug handbook, hidden debug interfaces, writing services, QEMU, tests, PR bar</td></tr><tr><td><a href="./arch/">arch/</a></td><td>System anatomy: the system map, the full repository tree map, hidden mechanisms, private headers + deep dives: boot flow, memory, scheduler, interrupts, ring 3, VFS, network, drivers, TUI</td></tr><tr><td><a href="./l1/">l1/</a></td><td>Ring-3 app development: the surface map, app anatomy, the wizard library, writing apps, service families</td></tr><tr><td><a href="./drivers/">drivers/</a></td><td>Driver bring-up manuals: 16 families</td></tr><tr><td><a href="./troubleshooting/">troubleshooting/</a></td><td>Error library: 61 errno codes + panics, the all-subsystem error catalog, silent failures, boot/network/storage/QEMU guides</td></tr><tr><td><a href="./internals/">internals/</a></td><td>Subsystem internals: watchdog, klog, health, crash dump, crypto seeding, OTA/A-B, the OCIRE guard channel</td></tr><tr><td><a href="./release/">release/</a></td><td>Maintainer guide: build system reference, guard scripts, CI gates, tool inventory (117), disaster recovery &amp; push channels, process SOP, versioning, website + wiki sync</td></tr></tbody></table><h2 id="quick-facts-3-0-0-wp-l1apps-merge" tabindex="-1">Quick facts (3.0.0-WP-l1apps-merge) <a class="header-anchor" href="#quick-facts-3-0-0-wp-l1apps-merge" aria-label="Permalink to &quot;Quick facts (3.0.0-WP-l1apps-merge)&quot;">​</a></h2><ul><li>296 shell commands - 284 ring-3 registry apps (the 8 merged mega-apps included) + 12 ush built-ins, zero commands in L0 (<code>help -a</code> in the guest)</li><li>20 SYS_L1SVC service categories / 208 numbered ops (INTERFACES.md, l1svc_defs.h)</li><li>54 syscalls (<code>ocos/services/sysapi/interface/svc_sysapi_syscall.h</code>)</li><li>158,474 lines of original source across 764 files</li><li>Apache 2.0, every file SPDX-tagged</li></ul>',9)])])}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
